async function saveSettings(){dialogBusy.value=true;await run(async()=>{settingsDoc.value=await consoleAPI('save_settings',{base_token:settingsDoc.value._settings_token,values:cleanFields(settingsSchema.value,settingsDoc.value)},true);message.value='Đã lưu cấu hình.'});dialogBusy.value=false}
async function ingestScale(){if(!scope.farm){error.value='Chọn vườn trước.';return}if(!scaleInput.reading_id)scaleInput.reading_id=crypto.randomUUID();if(!scaleInput.captured_at)scaleInput.captured_at=new Date().toISOString();await command('lotus_farm.api.ingest_scale',{farm:scope.farm,device_id:scaleInput.device_id,reading_id:scaleInput.reading_id,captured_at:scaleInput.captured_at,gross_kg:scaleInput.gross_kg,tare_kg:scaleInput.tare_kg})}
async function downloadPlantingTemplate(){const result=await run(()=>call('lotus_farm.forecast_setup.planting_template',{company:scope.company||null,farm:scope.farm||null,zone:scope.zone||null,block:scope.block||null}));if(!result)return;const csv='\uFEFF'+result.csv;const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=result.file_name||'lotus-ngay-trong.csv';a.click();URL.revokeObjectURL(url)}
async function downloadDataset(){const result=await run(()=>call('lotus_farm.reporting.dataset',{from_date:scope.from_date||scope.date,to_date:scope.to_date||scope.date,farm:scope.farm||null,company:scope.company||null,zone:scope.zone||null,block:scope.block||null,plot:null,cycle:scope.cycle||null}));if(!result)return;const url=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`lotus-dataset-${scope.farm||'all'}-${scope.from_date||scope.date}-${scope.to_date||scope.date}.json`;a.click();URL.revokeObjectURL(url)}
async function refreshOutbox(){outbox.value=await queueRows(session.user)}
function locate(){if(!navigator.geolocation){error.value='Thiết bị không hỗ trợ lấy vị trí.';return}navigator.geolocation.getCurrentPosition(p=>{fieldEvidence.latitude=p.coords.latitude;fieldEvidence.longitude=p.coords.longitude;fieldEvidence.gps_accuracy_m=p.coords.accuracy},e=>error.value=e.message,{enableHighAccuracy:true,timeout:12000})}
function capturePayload(){const values={};for(const key of schema.value?.capture_fields||[])if(Object.prototype.hasOwnProperty.call(editor.value,key)&&editor.value[key]!==''&&editor.value[key]!=null)values[key]=editor.value[key];return {client_event_id:editor.value._event_id||(editor.value._event_id=crypto.randomUUID()),farm:scope.farm||editor.value.farm,target_doctype:editor.value.doctype,values,captured_at:editor.value._captured_at||(editor.value._captured_at=new Date().toISOString()),latitude:fieldEvidence.latitude,longitude:fieldEvidence.longitude,gps_accuracy_m:fieldEvidence.gps_accuracy_m}}
async function queueEditor(){if(!schema.value?.capture_fields?.length){error.value='Phiếu này không hỗ trợ nhập hiện trường khi mất mạng.';return}const event=capturePayload();if(!event.farm){error.value='Chọn vườn trước.';return}await run(async()=>{await queueCapture(session.user,event,fieldEvidence.photo);await refreshOutbox();message.value='Đã giữ bản ghi trên máy. Khi có mạng bấm Đồng bộ.';editor.value=null})}
async function sendField(){if(!schema.value?.capture_fields?.length)return;const event=capturePayload();if(!event.farm){error.value='Chọn vườn trước.';return}dialogBusy.value=true;await run(async()=>{await queueCapture(session.user,event,fieldEvidence.photo);editor.value=null;await refreshOutbox();await syncOutbox();await load()});dialogBusy.value=false}
async function syncOutbox(){await run(async()=>{const current=await call('lotus_farm.field.session_info');if(current.user!==session.user)throw new Error('Tài khoản đã thay đổi; không gửi hàng chờ của người khác.');await syncCaptures(session.user,{call,upload:(file,user)=>upload(file,null,null,user)});await refreshOutbox();message.value='Đã xử lý hàng chờ; bản lỗi vẫn được giữ để kiểm tra.'})}
async function reconcileRow(row){await run(async()=>{let reason='';const status=await call('lotus_farm.field.capture_status',{client_event_id:row.event.client_event_id});if(!status.received){reason=window.prompt('Máy chủ chưa nhận bản này. Nếu muốn bỏ bản nhập sai, ghi lý do; để trống để giữ lại.')||''}await reconcileCapture(session.user,row.key,{call},reason);await refreshOutbox()})}
async function clearSentRows(){await clearSent(session.user);await refreshOutbox()}
const auditColumns=[{field:'field',headerName:'Trường'},{field:'before',headerName:'Trước'},{field:'after',headerName:'Sau'}]
const qcRows=computed(()=>qc.value?.defects||[])
const qcColumns=computed(()=>[{field:'label',headerName:'Nguyên nhân',minWidth:200},...(qc.value?.lots||[]).map(lot=>({colId:lot.name,headerName:lot.name,minWidth:160,type:'numericColumn',valueGetter:p=>(qc.value?.cells||[]).filter(c=>c.lot===lot.name&&c.defect===p.data.name).reduce((n,c)=>n+c.weight_kg,0),valueFormatter:p=>fmt(p.value)}))])
function openQcCell(event){if(event.colDef.colId)showTrace('Harvest Lot',event.colDef.colId)}
function changes(version){try{return JSON.parse(version.data).changed||[]}catch{return []}}
async function showTrace(type,name){trace.value=await run(()=>call(type==='Harvest Lot'?'lotus_farm.reporting.trace_lot':type==='Packout Run'?'lotus_farm.reporting.trace_packout':'lotus_farm.reporting.plot_history',type==='Harvest Lot'?{harvest_lot:name}:type==='Packout Run'?{packout:name}:{farm_plot:name}))}
async function transition(task,state){await command('lotus_farm.console.work_state',{plan:task.plan,line:task.line,state,reason:reason.value})}
function complete(task){workDialog.value=task;workActual.quantity=task.planned_qty;workActual.days=task.allocated_workdays;workActual.reason='';workActual.attribution=[]}
async function finish(){dialogBusy.value=true;await run(async()=>{const t=workDialog.value;await queueCapture(session.user,{client_event_id:workDialog.value.event_id??=(crypto.randomUUID()),farm:scope.farm,target_doctype:'Daily Work Result',captured_at:t.captured_at??=(new Date().toISOString()),values:{farm_block:t.farm_block,farm_plot:t.farm_plot,crop_cycle:t.crop_cycle,sucker_selection_batch:t.cohort||null,posting_date:scope.date,work_plan:t.plan,work_plan_line:t.line,completed_qty:workActual.quantity,actual_workdays:workActual.days,unfinished_reason:workActual.reason,actual_labor:workActual.attribution.map(a=>{const source=t.allocations.find(r=>r.name===a.allocation);return {employee:source?.employee||null,work_team:source?.employee?null:(source?.work_team||null),actual_workdays:a.days,completed_qty:a.quantity}})}});workDialog.value=null;await refreshOutbox();await syncOutbox();await load()});dialogBusy.value=false}
async function uploadSource(event){const file=event.target.files[0];if(!file)return;const result=await run(()=>upload(file,editor.value.doctype,editor.value.name));if(result)extra.file_url=result.file_url}
async function closePreview(){preview.value=await run(()=>call('lotus_farm.daily_api.preview_close',{farm:scope.farm,posting_date:scope.date,zone:scope.zone||null,block:scope.block||null,plot:null,cycle:scope.cycle||null}))}
const extra=reactive({warehouse:'',schedule_date:'',file_url:'',crop_cycle:'',base_profile:'',valid_from:'',valid_to:'',sample_from:'',sample_to:'',item:'',quantity:0,sales_order:'',sales_order_item:'',stock_reservation:'',trace_kind:'Harvest Lot',trace_query:'',trace_batch:''})
function typeChanged(){start.value=0;scope.status='';updateScope();load()}
function pageMore(delta){start.value=Math.max(0,start.value+delta);load()}
async function openHierarchy(row){if(page.value==='farms')go('farms/'+encodeURIComponent(row.name),{farm:row.name,company:row.company});else if(/^(farm|farms)\//.test(page.value))go('blocks/'+encodeURIComponent(row.name),{block:row.name});else go('map',{block:row.name,plot:'',cycle:''})}
onMounted(async()=>{await run(async()=>{await session.load();online.value=!session.offline;scope.fromQuery(routeScope(route),session.today,session.farms);if(companies.value.length===1)scope.company=companies.value[0];search.value=scope.search||'';sort.value=scope.sort||'modified desc';await refreshOutbox();if(!nav.value.some(([p])=>p===page.value)&&page.value==='today'&&nav.value.length)go(nav.value[0][0]);else await load()});window.addEventListener('lotus-cached-read',()=>{cached.value=true;online.value=false});window.addEventListener('online',async()=>{online.value=true;cached.value=false;await run(async()=>{const old=session.user;await session.load(true);if(old!==session.user){editor.value=null;workDialog.value=null;scope.clearBelow('company')}scope.fromQuery(routeScope(route),session.today,session.farms);await refreshOutbox();await load()})});window.addEventListener('offline',()=>{online.value=false})})
watch(()=>route.fullPath,()=>{if(session.ready){scope.fromQuery(routeScope(route),session.today,session.farms);search.value=scope.search||'';sort.value=scope.sort||'modified desc';start.value=0;load()}})
const workspaceActions=computed(()=>[...visibleHrNavigation(session).map(item=>({id:'hr-'+item.id,label:item.label,navigation:true,href:hrHref(item)})),...nav.value.filter(([id])=>!['nhan-su','cham-cong'].includes(id)).map(([id,label])=>({id,label,navigation:true,run:()=>go(id)})),...(session.capabilities.stock?[{id:'stock',label:'Quản lý kho',navigation:true,href:'/lotus/kho'}]:[]),...(session.commands.work?[{id:'assign',label:'Giao việc nhanh',navigation:true,href:'/lotus/cong-viec?action=assign'+(scope.farm?'&farm='+encodeURIComponent(scope.farm):'')}]:[])])
// Success messages show as toasts (errors stay inline next to the form).
useNoticeToast(message)
// Unsaved changes in the document editor: confirm before closing, warn before leaving the page,
// and keep a local draft of new documents so a closed tab or crash does not lose typing.
const editorSnapshot=ref('')
const {open:confirmOpen,title:confirmTitle,message:confirmMessage,alertOnly:confirmAlert,ask:askConfirm,finish:finishConfirm}=useWorkspaceConfirm()
const removeWorkspaceGuard=router.beforeEach(async(to,from)=>{
 const changed=to.path!==from.path||['buying_view','stock_view','company','warehouse'].some(k=>to.query[k]!==from.query[k])
 if(changed&&workspaceChild.value?.hasChanges?.()){
  if(!await askConfirm('Bỏ phần chưa lưu và chuyển màn hình?'))return false
  workspaceChild.value?.discardChanges?.()
 }
})
function preventWorkspaceUnload(event){if(workspaceChild.value?.hasChanges?.()){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',preventWorkspaceUnload))
onUnmounted(()=>{removeWorkspaceGuard();window.removeEventListener('beforeunload',preventWorkspaceUnload)})

const snapshotOf=doc=>schema.value&&doc?JSON.stringify(cleanFields(schema.value,doc)):''
const editorDirty=computed(()=>!!editor.value&&!!schema.value&&editor.value.docstatus!==1&&snapshotOf(editor.value)!==editorSnapshot.value)
async function closeEditor(){
 if(editorDirty.value&&!await askConfirm('Phiếu có thay đổi chưa lưu. Đóng và bỏ thay đổi?','Bỏ thay đổi?'))return
 if(editor.value&&!editor.value.name)clearDraft(editor.value.doctype)
 editor.value=null;audit.value=null;shift.value=null
}
function offerDraft(type,name){
 if(name)return
 const draft=loadDraft(type);if(!draft)return
 toast({title:'Có bản nháp chưa lưu',description:'Lưu lúc '+new Date(draft.savedAt).toLocaleString('vi-VN'),tone:'info',action:{label:'Khôi phục',run:()=>{if(editor.value?.doctype===type&&!editor.value.name)Object.assign(editor.value,draft.values)}}})
}
let draftTimer
watch(()=>editor.value&&!editor.value.name&&editorDirty.value?snapshotOf(editor.value):'',value=>{clearTimeout(draftTimer);if(value)draftTimer=setTimeout(()=>saveDraft(editor.value.doctype,cleanFields(schema.value,editor.value)),800)})
function beforeUnload(event){if(editorDirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload))

// Ctrl-K record search: only document types this session can open, via the permission-checked link_options.
const searchableDoctypes=['Farm','Farm Block','Farm Plot','Crop Cycle','Daily Work Plan','Daily Work Result','Harvest Actual','Harvest Forecast','Packout Run','Incoming Quality Inspection','Material Requirement','Daily Production Close']
async function searchRecords(text){
 const allowed=new Set(Object.values(session.modules||{}).flat())
 const types=searchableDoctypes.filter(type=>allowed.has(type))
 const groups=await Promise.all(types.map(type=>consoleAPI('link_options',{doctype:type,search:text,farm:scope.farm||undefined}).then(rows=>(rows||[]).slice(0,4).map(row=>({id:type+':'+row.value,record:true,kind:docLabel(type),label:row.label&&row.label!==row.value?row.label+' · '+row.value:row.value,run:()=>edit(type,row.value)}))).catch(()=>[])))
 return groups.flat().slice(0,20)
}

</script>

<template><a class="lotus-skip-link" href="#lotus-main">Bỏ qua tới nội dung</a><div class="app-shell lotus-ui workspace-shell" @click.capture="followWorkspaceLink" :class="{'mobile-landing':page==='mobile','map-workspace':page==='map','sidebar-collapsed':sidebarCollapsed}"><WorkspaceSidebar :nav="nav" :page="page" :hr-view="route.query.hr_view" :buying-view="route.query.buying_view" @go="go" /><main ref="workspaceMain" id="lotus-main" tabindex="-1"><WorkspaceBar :user="session.user" :title="workspaceTitle" :actions="workspaceActions" :navigate="navigateWorkspace" :record-search="searchRecords" /><WorkspaceScopeBar v-if="!embeddedComponent&&page!=='map'" :land="page!=='reports'||!['commerce','stock','people'].includes(reportTab)" :farm-visible="page!=='reports'||!['commerce','stock'].includes(reportTab)" :page="page" :busy="busy" :options="scopeOptions" :companies="companies" :farms="farms" @change="updateScope" @refresh="refresh" /><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="outbox.some(r=>!['Sent','Discarded'].includes(r.status))" class="notice"><UiButton variant="link" @click="outboxOpen=true">Có bản ghi chưa gửi · Xem để xử lý</UiButton></p><p v-if="busy" class="muted">Đang đọc số liệu…</p>
<p v-if="cached||session.offline" class="notice" role="status">Đang dùng dữ liệu đã lưu của {{session.user}}. Quyền, ngày và số liệu sẽ được kiểm tra lại khi gửi.</p><div v-show="embeddedComponent" class="workspace-module-host"><KeepAlive><component v-if="embeddedComponent" ref="workspaceChild" :is="embeddedComponent" :key="page" :navigation-key="['cong-viec','mua-hang','kho'].includes(page)?route.fullPath:undefined" :buying-view="route.query.buying_view" :stock-view="route.query.stock_view||route.query.tab" :company="route.query.company" :warehouse="route.query.warehouse" :hr-view="page==='nhan-su'?route.query.hr_view:undefined" :embedded="true" @navigation-consumed="consumeWorkspaceAction"/></KeepAlive></div><section v-if="page==='denied'" class="panel" role="alert"><h2>Không có quyền mở màn hình này</h2><p>Chọn một mục được phép trong menu hoặc đăng nhập lại.</p><a href="/login?redirect-to=/lotus/today">Đăng nhập</a></section><template v-else-if="embeddedComponent"></template><section v-else-if="page==='mobile'"><MobileHome :session="session" :farm="scope.farm" :online="online" :queued="queuedCount" @select="openMobileAction" @outbox="outboxOpen=true"/></section><section v-else-if="page==='today'"><div class="kpi-grid"><UiButton variant="outline" v-for="card in cards" :key="card.label" class="kpi" @click="go(card.route)"><span>{{card.label}}</span><strong>{{fmt(card.value)}}</strong><small>{{card.unit}} ↗</small></UiButton></div><section class="panel"><h2>Điểm cần xử lý</h2><div v-for="f in summary" :key="f.farm" class="farm-summary"><UiButton variant="outline" class="text-link" @click="go('farm/'+encodeURIComponent(f.farm),{farm:f.farm})">{{f.farm}} ↗</UiButton><span v-for="alert in f.alerts" :key="alert.kind" class="alert-chip">{{alert.kind}} · {{fmt(alert.value)}}</span><span v-if="!f.alerts.length" class="muted">Không có cảnh báo theo ngưỡng cấu hình.</span></div></section><section class="panel"><h2>Công việc ngày</h2><OpsList :rows="tasks" :columns="['farm','farm_plot','work_name','planned_qty','uom','completed_qty','required_workdays','allocated_workdays','status']" @open="go('work',{farm:$event.farm})"/></section><section class="panel"><h2>Khả năng cung ứng</h2><OpsList :rows="data?.forecast||[]" :columns="['farm','period_start_date','item','packed_forecast_kg','materialized_qty_kg','committed_qty_kg','available_to_promise_kg']" @open="edit('Harvest Forecast',$event.name)"/></section></section>
<section v-else-if="page==='plan-norm'"><PlanNormSettings :farm="scope.farm" :block="scope.block" :payload="data||{}" :loading="busy" @reload="load"/></section><section v-else-if="page==='forecast-onedrive'"><UiButton type="button" variant="outline" v-if="session.modules.plans?.length" @click="go('plan-norm')"><LotusIcon name="settings"/>Cấu hình kế hoạch & định mức</UiButton><Vip126RollingForecast v-if="!demoView&&(scope.farm==='LOTUS-222'||!scope.farm)" :farm="scope.farm||''" :block="scope.block||''"/><ForecastPlanner :payload="calendarData||{}" :loading="busy" :can-settings="!!session.creatable['Harvest Profile']" :can-edit-block="!!session.creatable['Farm Block']" :can-download-template="true" @download-template="downloadPlantingTemplate" @demo-changed="demoView=$event" @edit-block="edit('Farm Block',$event)" @reload="load" @settings="edit('Harvest Profile',$event)"/><LotusImportPreview v-if="!demoView&&(scope.farm==='LOTUS-222'||!scope.farm)" :farm="scope.farm||''" :block="scope.block||''"/><details v-if="!demoView" class="forecast-legacy"><summary>Phiếu dự thu, lịch theo tuần và các thao tác nâng cao</summary><ForecastWorkspace :payload="data||{}" :loading="busy" :can-create="!!session.creatable['Harvest Forecast']" @open="edit('Harvest Forecast',$event.name)" @create="createForecast" @revise="reviseForecast" @reload="load" @plan="go('plans')" @reports="go('reports',{from_date:data?.from_date,to_date:data?.to_date})"/></details></section>
 <section v-else-if="page==='reports'"><ReportsWorkspace :charts="charts" :busy="busy" :filters="reportFilters" @tab="reportTab=$event" @filters="reportFilters=$event;load()"><template #forecast><div class="panel"><div class="section-title"><h2>Dự thu trước thu 8 / 4 / 2 / 1 tuần</h2><UiButton variant="outline" @click="downloadDataset">Xuất dataset JSON</UiButton></div><p class="muted">Chỉ tính sai lệch khi nguồn thực tế đã nhận, QC, đóng gói và ghi kho đầy đủ.</p><OpsList :rows="data?.rows||[]" :columns="['farm','farm_plot','crop_cycle','horizon_weeks','forecast_kg','actual_kg','absolute_error_kg','signed_error_kg','change_kg','status']" @open="edit('Harvest Forecast',$event.forecast)"/><div class="kpi-grid"><div v-for="(metric,horizon) in data?.metrics||{}" :key="horizon" class="kpi"><span>Trước {{horizon}} tuần</span><strong>{{metric.wape==null?'—':fmt(metric.wape*100)+'%'}}</strong><small>Sai số tuyệt đối (WAPE) · lệch {{metric.bias==null?'—':fmt(metric.bias*100)+'%'}} · {{metric.sample_count}} mẫu</small></div></div><h2>Năng suất theo người / đội và loại công việc</h2><OpsList :rows="productivity?.rows||[]" :columns="['farm','work_type','employee','work_team','uom','completed_qty','actual_workdays','quantity_per_workday']"/><p class="muted">{{productivity?.unattributed?.length||0}} phiếu chỉ có số tổng; cần ghi thực tế theo người/đội để tính năng suất.</p><h2>Đề xuất hiệu chuẩn từ thực tế</h2><div class="schema-grid"><label>Bộ hệ số gốc<UiInput v-model="extra.base_profile" /></label><label>Vụ mẫu<UiInput v-model="extra.crop_cycle" /></label><label>Mẫu từ<UiInput type="date" v-model="extra.sample_from" /></label><label>Mẫu đến<UiInput type="date" v-model="extra.sample_to" /></label><label>Hiệu lực từ<UiInput type="date" v-model="extra.valid_from" /></label><label>Hiệu lực đến<UiInput type="date" v-model="extra.valid_to" /></label></div><UiButton variant="outline" v-if="session.commands.calibrate_harvest" @click="command('lotus_farm.learning.create_calibrated_profile',{base_profile:extra.base_profile,crop_cycle:extra.crop_cycle,from_date:extra.sample_from,to_date:extra.sample_to,valid_from:extra.valid_from,valid_to:extra.valid_to})">Tạo bộ hệ số dự thu nháp</UiButton><UiButton variant="outline" v-if="session.commands.calibrate_packout" @click="command('lotus_farm.learning.create_calibrated_packout',{base_profile:extra.base_profile,crop_cycle:extra.crop_cycle,from_date:extra.sample_from,to_date:extra.sample_to,valid_from:extra.valid_from,valid_to:extra.valid_to})">Tạo bộ hệ số đóng gói nháp</UiButton><h2>Tiến độ giao hàng</h2><p v-if="!scope.farm" class="muted">Chọn một vườn để xem đơn đã giao, còn phải giao và phần đã giữ nguồn.</p><OpsList v-else :rows="delivery" :columns="['sales_order','item','ordered_kg','delivered_kg','remaining_demand_kg','state']"/></div></template></ReportsWorkspace></section>
<section v-else-if="page==='trace'" class="panel"><h2>Truy xuất nguồn gốc</h2><div class="schema-grid"><label>Loại<UiSelect v-model="extra.trace_kind"><option value="Harvest Lot">Lô thu hoạch</option><option value="Packout Run">Đợt đóng gói</option><option value="Item">Vật tư / sản phẩm</option><option value="Farm Plot">Thửa</option></UiSelect></label><label>Mã cần tìm<UiInput v-model="extra.trace_query" @keyup.enter="traceSearch" /></label><label v-if="extra.trace_kind==='Item'">Lô kho (không bắt buộc)<UiInput v-model="extra.trace_batch" /></label></div><UiButton variant="outline" @click="traceSearch">Truy xuất</UiButton><template v-if="trace?.kind==='Harvest Lot'"><OpsList :rows="trace.result.sources||[]" :columns="['farm','farm_block','farm_plot','crop_cycle','harvest_actual','contributed_kg']"/><OpsList :rows="trace.result.qc||[]" :columns="['name','received_kg','accepted_kg','rejected_kg']"/><OpsList :rows="trace.result.packout_documents||[]" :columns="['name','packing_date','stock_entry']"/></template><template v-else-if="trace?.kind==='Packout Run'"><OpsList :rows="trace.result.sources||[]" :columns="['farm','farm_block','farm_plot','crop_cycle','harvest_lot','harvest_actual','fraction']"/><OpsList :rows="trace.result.outputs||[]" :columns="['item','batch','net_kg','output_type','grade','market']"/></template><template v-else-if="trace?.kind==='Item'"><article v-for="run in trace.result||[]" :key="run.packout" class="farm-summary"><UiButton variant="outline" @click="edit('Packout Run',run.packout)">{{run.packout}}</UiButton><span>{{run.farm}} · {{run.packing_date}} · {{run.stock_entry||'chưa ghi kho'}}</span></article><p v-if="trace&&!trace.result?.length" class="empty">Không tìm thấy thành phẩm phù hợp trong phạm vi được phép xem.</p></template><template v-else-if="trace?.kind==='Farm Plot'"><OpsList :rows="trace.result.events||[]" :columns="['date','doctype','name','crop_cycle']"/><OpsList :rows="trace.result.forecasts||[]" :columns="['name','supply_state','period_start_date','period_end_date','packed_forecast_kg']"/></template></section>
<section v-else-if="page==='map'" class="map-panel"><PlotMap :collection="mapData" :farm="scope.farm" :user="session.user" @reset="scope.zone='';scope.block='';scope.plot='';scope.cycle='';updateScope()" @open="scope.block=$event;scope.plot='';scope.cycle='';updateScope()"><template #filters><WorkspaceScopeBar page="map" :busy="busy" :options="scopeOptions" :companies="companies" :farms="farms" @change="updateScope" @refresh="refresh"/></template></PlotMap></section>
<section v-else-if="page==='admin/settings'" class="panel"><div class="section-title"><div><h2>Cấu hình Lotus</h2><p class="muted">Các ngưỡng và hệ số phải do vận hành duyệt; ứng dụng không tự đoán số.</p></div><UiButton variant="outline" v-if="settingsSchema?.permissions?.write" :loading="dialogBusy" @click="saveSettings">Lưu cấu hình</UiButton></div><SchemaForm v-if="settingsSchema&&settingsDoc" :schema="settingsSchema" :model="settingsDoc" :scope="scope" :readonly="!settingsSchema.permissions.write"/></section>
<section v-else-if="page==='farms'||/^(farm|farms|block|blocks)\//.test(page)" class="panel"><div class="section-title"><h2>{{page==='farms'?'Vườn':/^(farm|farms)\//.test(page)?'Lô trong vườn':'Lô chăm sóc'}}</h2><UiButton variant="outline" v-if="session.creatable[page==='farms'?'Farm':/^(farm|farms|block|blocks)\//.test(page)?'Farm Block':'Farm Block']" @click="edit(page==='farms'?'Farm':/^(farm|farms)\//.test(page)?'Farm Block':'Farm Plot',null,{farm:scope.farm,farm_block:scope.block})">Thêm</UiButton></div><OpsList :rows="tree.rows||[]" :columns="tree.columns||[]" :filter-values="tree.filter_values" :server-filters="columnFilters" @filter="applyColumns" @open="openHierarchy"/><Pagination :start="start" :count="tree.rows?.length||0" :has-more="!!tree.has_more" @update:start="value=>pageMore(value-start)"/><UiButton variant="outline" v-if="page!=='farms'" @click="go('work')">Việc trong phạm vi này</UiButton><UiButton variant="outline" v-if="page!=='farms'" @click="go('forecast')">Dự thu / sản lượng</UiButton></section>
<section v-else-if="/^(plot|plots)\//.test(page)"><section class="panel"><h2>{{data?.plot}} · {{data?.farm}} / {{data?.block}}</h2><OpsList :rows="data?.cycles||[]" :columns="['name','cycle_no','status','planting_date','variety']" @open="go('cycles/'+encodeURIComponent($event.name),{cycle:$event.name})"/><div class="tabs"><UiButton variant="outline" v-for="tab in tabs" :key="tab" :class="{active:tab===farmTab}" @click="farmTab=tab">{{tab}}</UiButton></div><div v-if="farmTab==='Sản lượng'"><OpsList :rows="data?.forecasts||[]" :columns="['name','supply_state','period_start_date','period_end_date','packed_forecast_kg']" @open="edit('Harvest Forecast',$event.name)"/></div><div v-else class="timeline"><UiButton variant="outline" v-for="event in (data?.events||[]).filter(e=>farmTab==='Công việc'?['Planting Event','Sucker Selection Batch','Bunch Operation','Daily Work Result','Fruit Measurement','Harvest Actual','Harvest Lot','Packout Run','Cycle Closing Report'].includes(e.doctype):farmTab==='Tổn thất'?['Bunch Cancellation','Disease Observation'].includes(e.doctype):farmTab==='Vật tư'?e.doctype==='Material Consumption':farmTab==='Nhân sự'?e.doctype==='Labor Allocation':farmTab==='QC'?e.doctype==='Incoming Quality Inspection':true)" :key="event.name" @click="edit(event.doctype,event.name)"><time>{{event.date}}</time><strong>{{docLabel(event.doctype)}}</strong><span>{{event.name}} ↗</span></UiButton><p v-if="farmTab==='Ảnh'" class="muted">Mở sự kiện để xem chứng cứ ảnh/GPS đã ghi.</p><p v-if="farmTab==='Lịch sử thay đổi'" class="muted">Mở chứng từ và chọn Lịch sử để xem trước/sau, người sửa và lý do.</p></div></section></section>
<section v-else-if="/^(cycle|cycles)\//.test(page)" class="panel"><div class="section-title"><div><p class="eyebrow">{{data?.cycle?.farm}} › {{data?.cycle?.farm_block}} › {{data?.cycle?.farm_plot}}</p><h2>Vụ {{data?.cycle?.name}}</h2></div><UiButton variant="outline" @click="edit('Crop Cycle',data?.cycle?.name)">Mở phiếu vụ</UiButton></div><div class="kpi-grid"><div v-for="field in ['cycle_no','cycle_type','status','variety','planting_date','parent_cycle']" :key="field" class="kpi"><span>{{label(field)}}</span><strong>{{fmt(data?.cycle?.[field])}}</strong></div></div><h3>Lịch sử thửa của vụ</h3><OpsList :rows="(data?.history?.events||[]).filter(e=>!e.crop_cycle||e.crop_cycle===data?.cycle?.name)" :columns="['date','doctype','name','crop_cycle']"/></section>
<section v-else><div class="view-controls"><UiSelect v-model="doctype" @change="typeChanged"><option v-for="t in types" :key="t" :value="t">{{docLabel(t)}}</option></UiSelect><UiInput v-model="search" placeholder="Tìm mã phiếu…" @keyup.enter="applyViewControls" /><UiSelect v-model="scope.status" @change="updateScope"><option value="">Tất cả trạng thái</option><option v-for="state in (key==='work'?['Planned','Ready','In Progress','Blocked','Completed']:list.status_options||[])" :key="state" :value="state">{{['0','1','2'].includes(state)?['Nháp','Đã nộp','Đã hủy'][Number(state)]:stateLabel(state)}}</option></UiSelect><UiSelect v-if="key==='work'" v-model="scope.view" @change="updateScope"><option value="list">Danh sách</option><option value="board">Bảng việc</option><option value="my-work">Việc của tôi</option><option value="at-risk">Việc có rủi ro</option></UiSelect><UiSelect v-model="sort" @change="applyViewControls"><option value="modified desc">Mới cập nhật</option><option value="modified asc">Cũ nhất</option><option value="name asc">Mã tăng dần</option></UiSelect><UiButton variant="outline" v-if="session.creatable[doctype]===true" @click="edit(doctype)">Thêm phiếu</UiButton><UiButton variant="outline" v-if="key==='work'" @click="scope.view=scope.view==='board'?'list':'board';updateScope()">{{scope.view==='board'?'Danh sách':'Bảng việc'}}</UiButton></div>
<section v-if="key==='work'&&overview" class="panel"><div class="section-title"><h2>Việc tại {{scope.farm}}</h2><UiButton variant="outline" v-if="session.commands.work" @click="command('lotus_farm.field.make_suggested_plan',{farm:scope.farm,posting_date:scope.date})">Gợi ý kế hoạch đến hạn</UiButton></div><div :class="scope.view==='board'?'kanban':'work-list'"><section v-for="state in (scope.view==='board'?['Planned','Ready','In Progress','Blocked','Completed']:['Tất cả'])" :key="state"><h3 v-if="scope.view==='board'">{{stateLabel(state)}}</h3><article v-for="task in overview.tasks.filter(t=>state==='Tất cả'||t.status===state).filter(t=>(!scope.block||t.farm_block===scope.block)&&(!scope.plot||t.farm_plot===scope.plot))" :key="task.line" class="work-card"><div class="section-title"><strong>{{task.work_name||task.work_type}}</strong><span class="pill">{{stateLabel(task.status)}}</span></div><UiButton variant="outline" class="text-link" @click="go('plots/'+encodeURIComponent(task.farm_plot),{plot:task.farm_plot})">{{task.farm_plot}} · {{task.crop_cycle}}</UiButton><p>{{fmt(task.completed_qty)}} / {{fmt(task.planned_qty)}} {{unitLabel(task.uom)}}</p><p class="muted">Công: {{fmt(task.allocated_workdays)}} / {{fmt(task.required_workdays)}} · {{task.work_team||task.responsible||'Chưa gán người phụ trách'}}</p><p class="muted">{{task.start_at||scope.date}} → {{task.due_at||scope.date}}</p><p v-if="task.blocked_reason" class="error" role="alert">{{task.blocked_reason}}</p><div v-if="!task.result" class="actions"><UiButton variant="outline" v-if="session.commands.work&&['Planned','Blocked'].includes(task.status)" @click="transition(task,'Ready')">Sẵn sàng</UiButton><UiButton variant="outline" v-if="session.commands.work&&['Ready','Blocked'].includes(task.status)" @click="transition(task,'In Progress')">Bắt đầu</UiButton><UiButton variant="outline" v-if="session.commands.work&&task.status!=='Blocked'" @click="reason='';workDialog={...task,blocking:true}">Bị chặn</UiButton><UiButton variant="outline" v-if="session.commands.capture&&session.creatable['Daily Work Result']" @click="complete(task)">Ghi kết quả</UiButton><UiButton variant="outline" v-if="session.creatable['Labor Allocation']" @click="edit('Labor Allocation',null,{work_plan:task.plan,work_plan_line:task.line,farm_block:task.farm_block,farm_plot:task.farm_plot,crop_cycle:task.crop_cycle,sucker_selection_batch:task.cohort})">Gán công</UiButton></div><UiButton variant="outline" v-else @click="edit('Daily Work Result',task.result)">Mở kết quả</UiButton></article></section></div></section>
<section v-if="key==='labor'&&overview" class="panel"><h2>Cần / có mặt / đã gán</h2><OpsList :rows="laborMatrix(overview.tasks,overview.labor)" :columns="['name','required','present','absent','allocated','gap','allocation_gap']"/><h3>Employee / Attendance ERP</h3><p class="muted">{{staff?.note}}</p><OpsList :rows="staff?.employees||[]" :columns="['employee','employee_name','attendance_known','remaining_workdays']"/></section>
<section v-if="key==='materials'&&material" class="panel"><h2>Nhu cầu còn lại và tồn khả dụng ERP</h2><p v-if="material.note" class="notice" role="status">{{material.note}}</p><OpsList :rows="material.rows" :columns="['item','uom','required_qty','actual_qty','available_qty','shortage_qty']"/><h3>Thực dùng so với định mức cho khối lượng đã làm</h3><OpsList :rows="material.usage" :columns="['requirement','item','uom','planned_qty','expected_for_actual','used_qty','variance_qty']" @open="edit('Material Requirement',$event.requirement)"/></section>
<section v-if="key==='packhouse'&&scope.farm&&session.capabilities.scale" class="panel"><h2>Nhận số cân</h2><div class="schema-grid"><label>Thiết bị cân<UiInput v-model="scaleInput.device_id" /></label><label>Mã lần cân<UiInput v-model="scaleInput.reading_id" placeholder="Tự sinh nếu để trống" /></label><label>Thời điểm<UiInput v-model="scaleInput.captured_at" type="datetime-local" /></label><label>Kg tổng<UiInput v-model.number="scaleInput.gross_kg" type="number" step="any" /></label><label>Kg bì<UiInput v-model.number="scaleInput.tare_kg" type="number" step="any" /></label></div><UiButton variant="outline" @click="ingestScale">Ghi số cân</UiButton><p class="muted">Máy chủ kiểm thiết bị, người tích hợp và kỳ hiệu chuẩn; không tin số cân chỉ vì trình duyệt gửi lên.</p></section>
<section v-if="key==='incoming-qc'&&qc" class="panel"><h2>Ma trận lỗi đầu vào · kg</h2><DataTable :rows="qcRows" :columns="qcColumns" @cell-open="openQcCell" /></section>
<section v-if="losses" class="panel"><h2>Hủy theo vườn / lô / nguyên nhân</h2><OpsList :rows="losses.by_reason" :columns="['farm','farm_block','reason','bunch_qty']"/></section>
<section v-if="key==='daily-close'&&!scope.farm&&data" class="panel"><h2>Trạng thái chốt theo vườn</h2><OpsList :rows="data.farms" :columns="['farm','closed','unclosed_dates']" @open="go('daily-close',{farm:$event.farm})"/></section>
<section v-if="key==='daily-close'&&scope.farm" class="panel"><h2>Kiểm tra trước chốt</h2><UiButton variant="outline" v-if="session.commands.preview_close" @click="closePreview">Xem đối soát</UiButton><OpsList v-if="preview" :rows="preview" :columns="['check_code','status','message','reference_doctype','reference_name']" @open="$event.reference_name&&edit($event.reference_doctype,$event.reference_name)"/><UiButton variant="outline" v-if="session.creatable['Daily Production Close']&&preview&&!preview.some(c=>c.status==='Block')" @click="edit('Daily Production Close')">Tạo phiếu chốt ngày</UiButton></section>
<section class="panel"><OpsList :rows="list.rows" :columns="list.columns" :filter-values="list.filter_values" :server-filters="columnFilters" @filter="applyColumns" :loading="busy" @open="edit(doctype,$event.name)"/><Pagination :start="start" :count="list.rows.length" :has-more="!!list.has_more" @update:start="value=>pageMore(value-start)"/></section></section>
</main></div><nav v-if="page!=='denied'" class="mobile-bottom-nav" aria-label="Điều hướng trên điện thoại"><UiButton variant="outline" v-for="tab in bottomTabs" :key="tab.id" :class="{active:page===tab.path}" :aria-current="page===tab.path?'page':undefined" @click="go(tab.path)"><LotusIcon :name="tab.icon" class="mobile-bottom-icon"/><small>{{tab.label}}</small></UiButton></nav>
<WorkspaceModal v-if="editor&&schema" :model-value="true" :title="editor.doctype==='Harvest Profile'?(editor.name?'CHỈNH SỬA BỘ HỆ SỐ':'THIẾT LẬP DỰ THU'):docLabel(editor.doctype)" width="1100px" :busy="dialogBusy" @update:model-value="!$event&&(closeEditor())"><p v-if="error" class="error" role="alert">{{error}}</p><div class="actions"><UiButton variant="outline" v-if="!editor.name&&schema.capture_fields?.length&&session.commands.capture&&schema.permissions.create" :loading="dialogBusy" @click="sendField">Gửi hiện trường</UiButton><UiButton variant="outline" v-if="!editor.name&&schema.capture_fields?.length&&session.commands.capture&&schema.permissions.create" @click="queueEditor">Lưu ngoại tuyến</UiButton><UiButton variant="outline" v-if="(!editor.name||editor.docstatus===0)&&(editor.name?schema.permissions.write:schema.permissions.create)&&(editor.doctype!=='Harvest Forecast'||editor.supply_state==='Draft')" :loading="dialogBusy" @click="save">{{editor.doctype==='Harvest Profile'?'Lưu thiết lập':'Lưu nháp'}}</UiButton><UiButton variant="outline" v-if="editor.name&&editor.doctype==='Harvest Forecast'&&editor.supply_state==='Draft'&&schema.permissions.write&&session.commands.forecast_release" :loading="dialogBusy" @click="releaseForecast">Phát hành dự thu</UiButton><ForecastCloseAction v-if="editor.doctype==='Harvest Forecast'" :forecast="editor" :can-close="!!(schema.permissions.write&&session.commands.forecast_release)" :disabled="dialogBusy" @busy="dialogBusy=$event" @closed="forecastClosed"/><UiButton variant="outline" v-if="editor.docstatus===0&&schema.is_submittable&&schema.permissions.submit" :loading="dialogBusy" @click="action('submit')">Nộp / duyệt</UiButton><UiButton variant="outline" v-if="editor.docstatus===1&&schema.permissions.cancel" @click="pendingDocumentAction='cancel';reason=''">Hủy phiếu</UiButton><UiButton variant="outline" v-if="editor.docstatus===2&&schema.permissions.amend" @click="pendingDocumentAction='amend';reason=''">Tạo bản sửa</UiButton><UiButton variant="outline" v-if="editor.name" @click="showAudit">Lịch sử</UiButton><UiButton variant="outline" v-if="['Harvest Lot','Packout Run'].includes(editor.doctype)&&editor.name" @click="showTrace(editor.doctype,editor.name)">Truy nguồn</UiButton><UiButton variant="outline" v-if="editor.doctype==='Harvest Lot'&&editor.name" @click="showQR">QR lô thu</UiButton><a v-if="editor.name" :href="'/app/'+editor.doctype.toLowerCase().replaceAll(' ','-')+'/'+encodeURIComponent(editor.name)" target="_blank">Mở ERP ↗</a></div><div v-if="pendingDocumentAction && editor.name" class="document-action-reason" role="group" aria-label="Xác nhận xử lý chứng từ"><p class="document-action-reason__title">{{pendingDocumentAction==='cancel'?'Xác nhận hủy phiếu':'Tạo bản sửa từ phiếu đã hủy'}}</p><label>{{pendingDocumentAction==='cancel'?'Lý do hủy phiếu':'Lý do sửa phiếu'}}<UiTextarea v-model="reason" rows="2" placeholder="Nhập lý do để xác nhận…"/></label><div class="actions"><UiButton variant="outline" type="button" :disabled="!reason.trim()||dialogBusy" :loading="dialogBusy" @click="action(pendingDocumentAction)">{{pendingDocumentAction==='cancel'?'Xác nhận hủy':'Xác nhận tạo bản sửa'}}</UiButton><UiButton variant="outline" type="button" :disabled="dialogBusy" @click="pendingDocumentAction='';reason=''">Không thực hiện</UiButton></div></div><div v-if="shift"><div class="tabs"><UiButton variant="outline" v-for="tab in ['General','Labor','Incoming','Incoming QC','Preprocessing','Packout','Material Recovery','Secondary Product','Reconciliation']" :key="tab" :class="{active:tab===shiftTab}" @click="shiftTab=tab">{{stateLabel(tab)}}</UiButton></div><div v-if="shiftTab==='Labor'"><OpsList :rows="shift.shift.labor" :columns="['employee','role_in_shift','workdays']"/></div><div v-else-if="shiftTab==='Preprocessing'||shiftTab==='Incoming'"><OpsList :rows="shift.shift.preprocessing" :columns="['harvest_lot','processed_bunches','processed_kg','started_at','ended_at']" @open="showTrace('Harvest Lot',$event.harvest_lot)"/></div><div v-else-if="shiftTab==='Packout'"><UiButton variant="outline" v-if="session.creatable['Packout Run']" @click="edit('Packout Run',null,{packhouse_shift:shift.shift.name})">Thêm đợt đóng gói</UiButton><OpsList :rows="shift.runs" :columns="['name','docstatus','stock_status']" @open="edit('Packout Run',$event.name)"/></div><div v-else-if="shiftTab==='Material Recovery'"><UiButton variant="outline" v-if="session.creatable['Material Recovery']" @click="edit('Material Recovery',null,{packhouse_shift:shift.shift.name})">Ghi thu hồi</UiButton><OpsList :rows="shift.recovery" :columns="['name','consumption','recovered_qty','stock_entry','docstatus']" @open="edit('Material Recovery',$event.name)"/></div><div v-else-if="shiftTab==='Secondary Product'"><UiButton variant="outline" v-if="session.creatable['Secondary Product Movement']" @click="edit('Secondary Product Movement',null,{packhouse_shift:shift.shift.name})">Ghi phụ phẩm</UiButton><OpsList :rows="shift.secondary" :columns="['name','item','quantity_kg','stock_entry','docstatus']" @open="edit('Secondary Product Movement',$event.name)"/></div><div v-else-if="shiftTab==='Reconciliation'" class="kpi-grid"><div v-for="field in ['input_kg','finished_kg','secondary_kg','loss_kg','cartons','packout_percent']" :key="field" class="kpi"><span>{{label(field)}}</span><strong>{{fmt(shift[field])}}</strong></div></div><UiButton variant="outline" v-else-if="shiftTab==='Incoming QC'" @click="editor=null;go('incoming-qc')">Mở ma trận lỗi và QC</UiButton></div><section v-if="!editor.name&&schema.capture_fields?.length&&session.commands.capture&&schema.permissions.create" class="panel"><h3>Chứng cứ hiện trường</h3><div class="actions"><UiButton variant="outline" @click="locate">Lấy GPS</UiButton><span class="muted">{{fieldEvidence.latitude==null?'Chưa lấy vị trí':`${fieldEvidence.latitude.toFixed(6)}, ${fieldEvidence.longitude.toFixed(6)} · ±${Math.round(fieldEvidence.gps_accuracy_m||0)} m`}}</span></div><label>Ảnh<input type="file" accept="image/*" capture="environment" @change="fieldEvidence.photo=$event.target.files[0]||null"/></label><p class="muted">Lưu ngoại tuyến giữ nguyên event ID, ảnh và tài khoản. Máy chủ vẫn kiểm quyền, ngày và chống gửi trùng khi đồng bộ.</p></section><ForecastForm v-if="editor.doctype==='Harvest Forecast'" :schema="schema" :model="editor" :scope="scope" :readonly="editor.supply_state!=='Draft'"/><HarvestProfileSettings v-else-if="editor.doctype==='Harvest Profile'" :schema="schema" :model="editor" :scope="scope" :readonly="editor.docstatus>0"/><SchemaForm v-else :schema="schema" :model="editor" :scope="scope" :readonly="editor.docstatus>0"/><section v-if="qr" class="panel"><h3>QR lô thu</h3><img :src="qr.image" :alt="'QR '+qr.harvest_lot" style="width:220px;max-width:100%"/><p><a :href="qr.url" target="_blank">Mở nguồn lô thu ↗</a></p></section><section v-if="evidence" class="panel"><h3>Chứng cứ hiện trường</h3><p>{{evidence.captured_by}} · {{evidence.captured_at}} · GPS {{evidence.latitude}}, {{evidence.longitude}} · ± {{evidence.gps_accuracy_m}} m</p><img v-if="evidence.photo" :src="evidence.photo" alt="Ảnh chứng cứ hiện trường" style="max-width:100%;max-height:350px"/><a :href="'/app/field-capture/'+editor.field_capture" target="_blank">Ảnh · GPS · thời điểm ghi ↗</a></section><section v-if="editor.name&&editor.supply_state==='Released'&&editor.doctype==='Harvest Forecast'&&session.commands.sales" class="panel"><h3>Cam kết bán và chuyển sang hàng kho</h3><div class="schema-grid"><label>Đơn bán ERP<UiInput v-model="extra.sales_order" @change="consoleAPI('order_lines',{sales_order:extra.sales_order}).then(r=>orderLines=r).catch(e=>error=e.message)"/></label><label>Dòng sản phẩm<UiSelect v-model="extra.sales_order_item"><option value="">Chọn dòng đơn</option><option v-for="line in orderLines" :key="line.name" :value="line.name">{{line.item}} · {{line.qty}} · {{line.delivery_date}}</option></UiSelect></label><label>Khối lượng giữ (kg)<UiInput type="number" min="0" step="any" v-model.number="extra.quantity" /></label><label>Phiếu giữ hàng kho ERP<UiInput v-model="extra.stock_reservation" /></label></div><UiButton variant="outline" @click="command('lotus_farm.allocations.reserve',{forecast:editor.name,sales_order:extra.sales_order,sales_order_item:extra.sales_order_item,qty_kg:extra.quantity,client_event_id:newEventID()})">Giữ phần dự thu</UiButton><div v-for="allocation in editor.allocations||[]" :key="allocation.name" class="farm-summary"><span>{{allocation.sales_order}} · {{allocation.item}} · {{allocation.reserved_qty_kg}} kg · {{allocation.allocation_state}}</span><UiButton variant="outline" v-if="allocation.allocation_state==='Reserved'" @click="command('lotus_farm.allocations.release',{forecast:editor.name,allocation:allocation.name})">Bỏ giữ dự thu</UiButton><UiButton variant="outline" v-if="allocation.allocation_state==='Reserved'" @click="command('lotus_farm.stock_bridge.link_stock_reservation',{forecast:editor.name,allocation:allocation.name,stock_reservation:extra.stock_reservation,qty_kg:extra.quantity})">Chuyển phần đã có hàng kho</UiButton></div></section><section v-if="editor.name&&editor.doctype==='Supply Reconciliation'&&editor.state==='Approved'&&session.commands.reconcile" class="panel"><UiButton variant="outline" @click="command('lotus_farm.reconciliation.execute',{reconciliation:editor.name})">Áp dụng đối soát đã duyệt</UiButton></section><section v-if="editor.name&&editor.docstatus===1&&editor.doctype==='Daily Work Plan'&&session.commands.work" class="panel"><UiButton variant="outline" @click="command('lotus_farm.daily_api.create_requirements',{work_plan:editor.name})">Tính nhu cầu vật tư</UiButton></section><section v-if="editor.name&&editor.docstatus===1&&editor.doctype==='Material Requirement'&&session.commands.work" class="panel"><h3>Cấp / mua vật tư</h3><label>Kho<UiInput v-model="extra.warehouse" /></label><label>Ngày cần<UiInput type="date" v-model="extra.schedule_date" /></label><UiButton variant="outline" @click="command('lotus_farm.daily_api.create_material_request',{requirement:editor.name,warehouse:extra.warehouse,schedule_date:extra.schedule_date||scope.date})">Tạo đề nghị mua phần thiếu</UiButton><a href="/lotus/kho">Nhu cầu và cấp vật tư trong kho Lotus</a><p class="muted">Ghi lượng thực dùng và thu hồi theo dòng phiếu xuất đã ghi sổ.</p></section><section v-if="editor.name&&editor.docstatus===1&&editor.doctype==='Packout Run'&&session.commands.repack" class="panel"><UiButton variant="outline" @click="command('lotus_farm.stock_bridge.make_repack_entry',{packout:editor.name})">Tạo phiếu nhập thành phẩm ERP</UiButton></section><section v-if="editor.name&&editor.doctype==='Source Import Batch'&&session.commands.imports" class="panel"><UiButton variant="outline" @click="command('lotus_farm.importing.preview_import',{batch:editor.name}).then(r=>importPreview=r)">Kiểm tra thử</UiButton><UiButton variant="outline" @click="command('lotus_farm.importing.import_rows',{batch:editor.name})">Tạo giao dịch nháp</UiButton><OpsList v-if="importPreview" :rows="importPreview" :columns="['row','status','target_doctype','error']"/></section><section v-if="editor.name&&editor.doctype==='Integration Task'&&session.commands.imports" class="panel"><UiButton variant="outline" @click="command('lotus_farm.importing.run_task',{task:editor.name})">Chạy / thử lại nhập nguồn</UiButton></section><section v-if="editor.name&&editor.doctype==='Source File Registry'&&session.commands.imports" class="panel"><label>Bảng ánh xạ đã duyệt<UiInput v-model="extra.base_profile" /></label><label>File Excel nguồn<input type="file" accept=".xlsx" @change="uploadSource"/></label><p v-if="extra.file_url" class="notice" role="status">Đã tải file nguồn private.</p><UiButton variant="outline" @click="command('lotus_farm.importing.stage_workbook',{source_file:editor.name,mapping:extra.base_profile,farm:scope.farm,file_url:extra.file_url})">Tạo dữ liệu tạm</UiButton></section><section v-if="audit" class="panel audit-drawer"><h3>Lịch sử thay đổi</h3><p>{{audit.owner}} · tạo {{audit.created}}</p><article v-for="version in audit.versions" :key="version.name"><strong>{{version.owner}} · {{version.creation}}</strong><DataTable :rows="changes(version).map(c=>({field:c[0],before:c[1],after:c[2]}))" :columns="auditColumns" /><details><summary>Chi tiết bảng con</summary><pre>{{JSON.stringify(JSON.parse(version.data),null,2)}}</pre></details></article><article v-for="comment in audit.comments" :key="comment.creation"><strong>{{comment.owner}} · {{comment.creation}}</strong><p>{{comment.content.replace(/<[^>]*>/g,'')}}</p></article></section></WorkspaceModal>
<WorkspaceModal v-if="outboxOpen" :model-value="true" title="Hàng chờ hiện trường" width="640px" :busy="dialogBusy" @update:model-value="!$event&&(outboxOpen=false)"><p class="muted">Chỉ hiển thị bản của {{session.user}}.</p><div class="actions"><UiButton variant="outline" :disabled="!online" @click="syncOutbox">Đồng bộ</UiButton><UiButton variant="outline" @click="clearSentRows">Xóa bản đã gửi</UiButton></div><article v-for="row in outbox" :key="row.key" class="child-row"><strong>{{docLabel(row.event.target_doctype)}} · {{row.status}}</strong><p class="muted">{{row.created}} · {{row.event.client_event_id}}</p><p v-if="row.error" class="error" role="alert">{{row.error}}</p><p v-if="row.result?.document">Máy chủ: {{row.result.document}}</p><UiButton variant="outline" v-if="row.status==='Error'&&online" @click="reconcileRow(row)">Kiểm tra máy chủ / bỏ bản sai</UiButton></article><p v-if="!outbox.length" class="empty">Không có bản ghi trong hàng chờ.</p></WorkspaceModal><WorkspaceModal v-if="workDialog" :model-value="true" :title="(workDialog.blocking?'Lý do bị chặn':'Ghi kết quả')+' · '+(workDialog.work_name||workDialog.work_type)" width="720px" :busy="dialogBusy" @update:model-value="!$event&&(workDialog=null)"><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="!workDialog.blocking"><label>Khối lượng thực tế · {{unitLabel(workDialog.uom)}}<UiInput type="number" min="0" step="any" v-model.number="workActual.quantity" /></label><label>Công thực tế<UiInput type="number" min="0" step="any" v-model.number="workActual.days" /></label><label>Lý do chưa hoàn thành<UiTextarea v-model="workActual.reason"/></label><section v-if="workDialog.allocations?.length"><h3>Phân bổ thực tế theo người / đội</h3><UiButton variant="outline" @click="workActual.attribution.push({allocation:workDialog.allocations[0].name,quantity:0,days:0})">Thêm người / đội</UiButton><div v-for="(row,index) in workActual.attribution" :key="index" class="child-row"><label>Người / đội<UiSelect v-model="row.allocation"><option v-for="allocation in workDialog.allocations" :key="allocation.name" :value="allocation.name">{{allocation.employee||allocation.work_team}} · {{allocation.allocated_workdays}} công</option></UiSelect></label><label>Khối lượng<UiInput type="number" min="0" step="any" v-model.number="row.quantity" /></label><label>Công<UiInput type="number" min="0" step="any" v-model.number="row.days" /></label><UiButton variant="outline" @click="workActual.attribution.splice(index,1)">Xóa dòng</UiButton></div><small class="muted">Tổng khối lượng và công từng dòng phải khớp kết quả. Không tự chia năng suất cho người khi chưa có số thực tế.</small></section><UiButton variant="outline" :loading="dialogBusy" @click="finish">Nộp kết quả</UiButton></template><template v-else><UiTextarea v-model="reason"/><UiButton variant="outline" @click="transition(workDialog,'Blocked').then(()=>{if(!error)workDialog=null})">Lưu trạng thái</UiButton></template></WorkspaceModal>
<WorkspaceModal v-if="trace&&page!=='trace'" :model-value="true" title="Truy nguồn" width="1100px" :busy="dialogBusy" @update:model-value="!$event&&(trace=null)"><OpsList :rows="trace.sources||[]" :columns="['company','farm','farm_block','farm_plot','crop_cycle','harvest_actual','contributed_kg','fraction']" @open="edit('Harvest Actual',$event.harvest_actual)"/><OpsList :rows="trace.qc||[]" :columns="['name','received_kg','accepted_kg','rejected_kg']" @open="edit('Incoming Quality Inspection',$event.name)"/><OpsList :rows="trace.outputs||[]" :columns="['item','batch','net_kg','output_type','grade','market']"/><UiButton variant="outline" v-for="run in trace.packout||[]" :key="run" @click="trace=null;edit('Packout Run',run)">{{run}}</UiButton><p class="muted">ID nguồn giữ nguyên; mở thửa hoặc chứng từ liên quan để xem lịch sử.</p><UiButton variant="outline" v-for="source in trace.sources||[]" :key="source.harvest_actual" @click="trace=null;go('plots/'+encodeURIComponent(source.farm_plot),{farm:source.farm,block:source.farm_block,plot:source.farm_plot})">{{source.farm_plot}} · {{source.harvest_actual}}</UiButton></WorkspaceModal><WorkspaceConfirm :open="confirmOpen" :title="confirmTitle" :message="confirmMessage" :alert-only="confirmAlert" @answer="finishConfirm"/><Toaster/>
</template>
